{{-- A segmented control. items: [['label' => 'All', 'href' => '/stats', 'on' => true, 'data' => ['map-layer' => 'paths']]]. Links by default, toggle buttons with `buttons`;
     an item's `data` becomes data attributes of its button. A link item with `disabled` is a muted label that cannot be followed. --}}
@props(['label', 'items', 'buttons' => false])
<div class="seg" role="group" aria-label="{{ $label }}">@foreach ($items as $item)@if ($buttons)<button type="button" aria-pressed="{{ empty($item['on']) ? 'false' : 'true' }}"@foreach ($item['data'] ?? [] as $name => $value) data-{{ $name }}="{{ $value }}"@endforeach>{{ $item['label'] }}</button>@elseif (! empty($item['disabled']))<span class="off" aria-disabled="true">{{ $item['label'] }}</span>@else<a href="{{ $item['href'] ?? '#' }}"@if (! empty($item['on'])) aria-current="true"@endif>{{ $item['label'] }}</a>@endif@endforeach</div>
